package net.civeira.phylax.feature.observe.observedissuealias.domain.valueholder;

import java.util.Optional;

import org.junit.jupiter.api.Assertions;
import org.junit.jupiter.api.DisplayName;
import org.junit.jupiter.api.Test;
import org.mockito.Mockito;

import net.civeira.phylax.common.value.validation.ConstraintFailList;
import net.civeira.phylax.feature.observe.observedissuealias.domain.ObservedIssueAlias;
import net.civeira.phylax.feature.observe.observedissuealias.domain.valueobject.FingerprintVO;

class FingerprintValueHolderUnitTest {

  /**
   * @autogenerated ValueHolderGenerator
   */
  @Test
  @DisplayName("Test assign plain values on the holder of fingerprint of observed issue alias")
  void test_fingerprint_value_holder_assign_plain_value() {
    Object holder = new Object();
    FingerprintValueHolder<Object> value = new FingerprintValueHolder<>(holder);
    Assertions.assertSame(holder, value.fingerprint("one"), "Setters must return the holder");
    Assertions.assertTrue(value.getFingerprintValue().isPresent(),
        "The plain value must be stored");
    Assertions.assertEquals("one", value.getFingerprint().orElse(null),
        "The plain value must be recovered");
  }

  /**
   * @autogenerated ValueHolderGenerator
   */
  @Test
  @DisplayName("Test assign value objects on the holder of fingerprint of observed issue alias")
  void test_fingerprint_value_holder_assign_value_object() {
    Object holder = new Object();
    FingerprintValueHolder<Object> value = new FingerprintValueHolder<>(holder);
    FingerprintVO vo = FingerprintVO.from("one");
    Assertions.assertFalse(value.getFingerprintValue().isPresent(), "A new holder must be empty");
    Assertions.assertSame(holder, value.fingerprint(vo), "Setters must return the holder");
    Assertions.assertSame(vo, value.getFingerprintValue().orElseThrow());
    Assertions.assertSame(holder, value.fingerprint(Optional.empty()));
    Assertions.assertFalse(value.getFingerprintValue().isPresent(),
        "An empty optional must clear the value");
    Assertions.assertSame(holder, value.fingerprint(Optional.of(vo)));
    Assertions.assertSame(vo, value.getFingerprintValue().orElseThrow());
  }

  /**
   * @autogenerated ValueHolderGenerator
   */
  @Test
  @DisplayName("Test read the value of the holder of fingerprint of observed issue alias against the original")
  void test_fingerprint_value_holder_read() {
    Object holder = new Object();
    FingerprintValueHolder<Object> value = new FingerprintValueHolder<>(holder);
    FingerprintVO vo = FingerprintVO.from("one");
    FingerprintVO other = FingerprintVO.from("one");
    ObservedIssueAlias original = Mockito.mock(ObservedIssueAlias.class);
    Mockito.when(original.getFingerprintValue()).thenReturn(other);
    ConstraintFailList fails = new ConstraintFailList();
    Assertions.assertSame(other, value.readFingerprint(Optional.of(original), fails),
        "Without value, the original must be used");
    Assertions.assertTrue(fails.isEmpty());
    Assertions.assertNull(value.readFingerprint(Optional.empty(), fails),
        "Without value and original there is no result");
    Assertions.assertFalse(fails.isEmpty(), "A required value must be reported as missing");
    value.fingerprint(vo);
    ConstraintFailList others = new ConstraintFailList();
    Assertions.assertSame(vo, value.readFingerprint(Optional.of(original), others),
        "With value, the original is ignored");
    Assertions.assertSame(vo, value.readFingerprint(Optional.empty(), others));
    Assertions.assertTrue(others.isEmpty());
  }

  /**
   * @autogenerated ValueHolderGenerator
   */
  @Test
  @DisplayName("Test unset the value of the holder of fingerprint of observed issue alias")
  void test_fingerprint_value_holder_unset() {
    Object holder = new Object();
    FingerprintValueHolder<Object> value = new FingerprintValueHolder<>(holder);
    FingerprintVO vo = FingerprintVO.from("one");
    value.fingerprint(vo);
    Assertions.assertSame(holder, value.unsetFingerprintIfMatches("fingerprint_other"));
    Assertions.assertTrue(value.getFingerprintValue().isPresent(),
        "Other field name must keep the value");
    Assertions.assertSame(holder, value.unsetFingerprintIfMatches("fingerprint"));
    Assertions.assertFalse(value.getFingerprintValue().isPresent(),
        "The field name must clear the value");
    value.fingerprint(vo);
    Assertions.assertSame(holder, value.unsetFingerprint());
    Assertions.assertFalse(value.getFingerprintValue().isPresent(), "Unset must clear the value");
  }
}
